$ErrorActionPreference='Stop'; $root='D:\IOT Trung\code_full_server'; $file=Join-Path $root 'scripts/inspect_incident_counts.py'; $b64=[Convert]::ToBase64String([IO.File]::ReadAllBytes($file)); $cmd="echo $b64 | base64 -d > /tmp/inspect_incident_counts.py; set -a; . /etc/smiot/app.env; set +a; cd /opt/smiot; sudo -E -u smiot env PYTHONPATH=/opt/smiot /opt/smiot/.venv/bin/python /tmp/inspect_incident_counts.py"; $p=Join-Path $env:TEMP 'inspect-incidents.json'; [IO.File]::WriteAllText($p,(@{commands=@($cmd)}|ConvertTo-Json -Compress),[Text.UTF8Encoding]::new($false)); $id=(aws ssm send-command --profile aws-moi --region ap-southeast-2 --instance-ids i-00bf2d3591d3ee0a2 --document-name AWS-RunShellScript --parameters file://$p --comment 'Inspect incident recovery counts' --query Command.CommandId --output text).Trim(); do {Start-Sleep 3; $r=aws ssm get-command-invocation --profile aws-moi --region ap-southeast-2 --command-id $id --instance-id i-00bf2d3591d3ee0a2 --output json|ConvertFrom-Json; if($r.Status -in @('Success','Failed','Cancelled','TimedOut')){$r.StandardOutputContent; if($r.StandardErrorContent){$r.StandardErrorContent}; break}}while($true); Remove-Item $p -Force
